class OutcomeException(BaseException):
    """OutcomeException and its subclass instances indicate and contain info
    about test and collection outcomes."""

    def __init__(self, msg: str | None = None, pytrace: bool = True) -> None:
        if msg is not None and not isinstance(msg, str):
            error_msg = (  # type: ignore[unreachable]
                "{} expected string as 'msg' parameter, got '{}' instead.\n"
                "Perhaps you meant to use a mark?"
            )
            raise TypeError(error_msg.format(type(self).__name__, type(msg).__name__))
        super().__init__(msg)
        self.msg = msg
        self.pytrace = pytrace

    def __repr__(self) -> str:
        if self.msg is not None:
            return self.msg
        return f"<{self.__class__.__name__} instance>"

    __str__ = __repr__

def lex(self, input: str) -> Iterator[Token]:
    pos = 0
    while pos < len(input):
        if input[pos] in (" ", "\t"):
            pos += 1
        elif input[pos] == "(":
            yield Token(TokenType.LPAREN, "(", pos)
            pos += 1
        elif input[pos] == ")":
            yield Token(TokenType.RPAREN, ")", pos)
            pos += 1
        elif input[pos] == "=":
            yield Token(TokenType.EQUAL, "=", pos)
            pos += 1
        elif input[pos] == ",":
            yield Token(TokenType.COMMA, ",", pos)
            pos += 1
        elif (quote_char := input[pos]) in ("'", '"'):
            end_quote_pos = input.find(quote_char, pos + 1)
            if end_quote_pos == -1:
                raise ParseError(
                    pos + 1,
                    f'closing quote "{quote_char}" is missing',
                )
            value = input[pos : end_quote_pos + 1]
            if (backslash_pos := input.find("\\")) != -1:
                raise ParseError(
                    backslash_pos + 1,
                    r'escaping with "\" not supported in marker expression',
                )
            yield Token(TokenType.STRING, value, pos)
            pos += len(value)
        else:
            match = re.match(r"(:?\w|:|\+|-|\.|\[|\]|\\|/)+", input[pos:])
            if match:
                value = match.group(0)
                if value == "or":
                    yield Token(TokenType.OR, value, pos)
                elif value == "and":
                    yield Token(TokenType.AND, value, pos)
                elif value == "not":
                    yield Token(TokenType.NOT, value, pos)
                else:
                    yield Token(TokenType.IDENT, value, pos)
                pos += len(value)
            else:
                raise ParseError(
                    pos + 1,
                    f'unexpected character "{input[pos]}"',
                )
    yield Token(TokenType.EOF, "", pos)

